import sys

def main():
    s = sys.stdin.read().split()[0]
    for ch in s:
        if ch < '0' or ch > '9':
            print('INVALID')
            return
    v = sum(ord(ch) - 48 for ch in s)
    while v >= 16:
        t = 0
        while v:
            v, d = divmod(v, 16)
            t += d
        v = t
    print('0123456789ABCDEF'[v])

main()

